      var g = this.$refs.overview_g.getBBox();
      var parentWidth = rootSvg.parentNode.offsetWidth; //svg父级的宽度
      var parentHeight = rootSvg.parentNode.offsetHeight; //svg父级的高度

      rootSvg.setAttribute("width", parentWidth);
      rootSvg.setAttribute("height", parentHeight);
      // viewBox="0 0 150 360
      // rootSvg.setAttribute("viewBox",`${g.x} ${g.y} ${g.width} ${g.height}`)
      rootSvg.setAttribute(
        "viewBox",
        "" + g.x + " " + (g.y-30 )+ " " + g.width + " " + (g.height + 40) + ""
      );
    },
  },
};
</script>

